                    bxa = wasm_i32x4_add(bxa, wasm_i32x4_dot_i16x8(GX[v], e)); bya = wasm_i32x4_add(bya, wasm_i32x4_dot_i16x8(GY[v], e));
                    ea = wasm_i32x4_add(ea, wasm_i32x4_extadd_pairwise_i16x8(wasm_i16x8_abs(e)));
